parameters.jsCode:
const raw = $input.first().json;
const parsed = (raw && typeof raw.output === 'object' && raw.output !== null) ? raw.output : raw;
const deflection = 'I do not have that detail to hand, so the agent will go through the current options with you.';

let text = (typeof parsed.answer_text === 'string') ? parsed.answer_text.trim() : '';
let grounded = parsed.grounded === true;

const sources = Array.isArray(parsed.sources) ? parsed.sources.filter(function (s) { return typeof s === 'string' && s.length > 0; }) : [];
if (grounded && sources.length === 0) { grounded = false; }

// grounded used to be worked out here and then thrown away: whatever the model
// wrote went to the lead word for word. That is how "I currently do not have any
// properties listed within your specified budget range" was sent to a lead while
// nine matching units sat in the catalogue. Nothing ungrounded is quotable.
if (!grounded) { text = deflection; }
if (!text) { text = deflection; grounded = false; }

return [{ json: { ok: true, answer_text: text, grounded: grounded, sources: sources } }];
